func ptrPayCode(p unsafe.Pointer, c int32) any {
	r := (*paycode.PayCode)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Status))
	case 4:
		return (*string)(unsafe.Pointer(&r.Direction))
	case 5:
		return &r.Code
	case 6:
		return &r.Name
	case 7:
		return &r.Description
	case 8:
		return &r.Taxable
	case 9:
		return &r.CountsTowardGuarantee
	case 10:
		return (**string)(unsafe.Pointer(&r.GLAccountID))
	case 11:
		return &r.DefaultAmountMinor
	case 12:
		return &r.IsSystem
	case 13:
		return &r.Version
	case 14:
		return &r.CreatedAt
	case 15:
		return &r.UpdatedAt
	}
	return nil
}

func valuePayCode(p unsafe.Pointer, c int32) any {
	r := (*paycode.PayCode)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Status)
	case 4:
		return string(r.Direction)
	case 5:
		return r.Code
	case 6:
		return r.Name
	case 7:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 8:
		return r.Taxable
	case 9:
		return r.CountsTowardGuarantee
	case 10:
		if r.GLAccountID == nil {
			return nil
		}
		return string(*r.GLAccountID)
	case 11:
		if r.DefaultAmountMinor == nil {
			return nil
		}
		return *r.DefaultAmountMinor
	case 12:
		return r.IsSystem
	case 13:
		return r.Version
	case 14:
		return r.CreatedAt
	case 15:
		return r.UpdatedAt
	}
	return nil
}

